package com.trampolim.api.fairs;
import java.time.*;import java.util.*;
import static com.trampolim.api.fairs.FairRules.*;
import com.trampolim.api.radar.RadarBridge;import com.trampolim.api.hub.HubService;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
/** Registration data remains exclusively in the user's own trail. */
public class FairRegistrationStore {
 private final JdbcTemplate db;private final String users;private final TransactionTemplate tx;private final RadarBridge bridge;
 public FairRegistrationStore(JdbcTemplate db,PlatformTransactionManager manager,RadarBridge bridge,boolean student){this.db=db;tx=new TransactionTemplate(manager);this.bridge=bridge;users=student?"student_users":"app_users";}
 private String active(){return users.equals("app_users")?"email_verified=TRUE AND account_type='PERSON'":"email_verified=TRUE AND account_status='ACTIVE'";}
 private long user(String email,boolean lock){if(email==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);return db.queryForList("SELECT id FROM "+users+" WHERE LOWER(email)=LOWER(?) AND "+active()+(lock?" FOR UPDATE":""),Long.class,email).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Use sua conta verificada desta trilha."));}
 private List<Map<String,Object>> rows(long uid,long event){return db.queryForList("SELECT * FROM job_fair_registrations WHERE user_id=? AND event_id=?",uid,event);}
 private Map<String,Object> view(Map<String,Object> row){var result=new LinkedHashMap<>(row);result.remove("user_id");result.remove("request_key");result.remove("request_hash");result.put("notice","Inscrição da própria conta; não reserva vaga de emprego, assento ou contratação. Confira a situação atual do evento.");return result;}
 public Map<String,Object> get(String email,long event){long uid=user(email,false);var stored=rows(uid,event);var result=stored.isEmpty()?new LinkedHashMap<String,Object>(Map.of("exists",false,"revision",0)):new LinkedHashMap<>(view(stored.getFirst()));if(!stored.isEmpty())result.put("exists",true);try{var source=bridge.get("/public/job-fairs/"+event);result.put("event",bridge.convert(source,Map.class));result.put("sourceStatus","AVAILABLE");}catch(ResponseStatusException unavailable){result.put("sourceStatus",unavailable.getStatusCode().value()==404?"NOT_PUBLIC":"UNAVAILABLE");}return result;}
 public Map<String,Object> join(String email,long event,Registration input){if(event<1||input==null||!input.consent()||input.expectedRevision()<0||input.requestKey()==null)bad("Confirme a inscrição e informe revisão e requestKey.");long uid=user(email,false);String hash=RadarBridge.hash(event+":"+input.expectedRevision()+":true");var initial=rows(uid,event);if(!initial.isEmpty()&&input.requestKey().equals(initial.getFirst().get("request_key"))){if(!hash.equals(initial.getFirst().get("request_hash")))conflict();return view(initial.getFirst());}
  var source=bridge.get("/public/job-fairs/"+event);if(source.path("id").asLong()!=event||!source.path("registrationOpen").asBoolean()||source.path("organization_id").asLong()<1)throw new ResponseStatusException(HttpStatus.CONFLICT,"O evento não está com inscrições abertas.");long org=source.path("organization_id").asLong();Instant ends=instant(source.path("ends_at").asText());Instant checked=Instant.now();
  return tx.execute(status->{user(email,true);if(!ends.isAfter(Instant.now()))conflict();var old=rows(uid,event);if(!old.isEmpty()&&input.requestKey().equals(old.getFirst().get("request_key"))){if(!hash.equals(old.getFirst().get("request_hash")))conflict();return view(old.getFirst());}long current=old.isEmpty()?0:number(old.getFirst(),"revision");if(current!=input.expectedRevision())conflict();if(!old.isEmpty()&&old.getFirst().get("status").equals("REGISTERED"))return view(old.getFirst());db.update("INSERT INTO job_fair_registrations(user_id,event_id,organization_id,receipt,status,revision,consent_at,source_checked_at,request_key,request_hash) VALUES (?,?,?,?,'REGISTERED',1,CURRENT_TIMESTAMP,?,?,?) ON CONFLICT(user_id,event_id) DO UPDATE SET status='REGISTERED',revision=job_fair_registrations.revision+1,consent_at=CURRENT_TIMESTAMP,source_checked_at=EXCLUDED.source_checked_at,updated_at=CURRENT_TIMESTAMP,request_key=EXCLUDED.request_key,request_hash=EXCLUDED.request_hash",uid,event,org,UUID.randomUUID(),java.sql.Timestamp.from(checked),input.requestKey(),hash);return view(rows(uid,event).getFirst());});
 }
 public void withdraw(String email,long event,long expected){if(event<1||expected<0)bad("Revisão inválida.");tx.executeWithoutResult(status->{long uid=user(email,true);var old=rows(uid,event);if(old.isEmpty()||old.getFirst().get("status").equals("WITHDRAWN"))return;if(number(old.getFirst(),"revision")!=expected)conflict();db.update("UPDATE job_fair_registrations SET status='WITHDRAWN',revision=revision+1,request_key=NULL,request_hash=NULL,updated_at=CURRENT_TIMESTAMP WHERE user_id=? AND event_id=?",uid,event);});}
 public Map<String,Object> list(String email,long before,int limit){long uid=user(email,false);page(before,limit);var list=db.queryForList("SELECT event_id AS id,event_id,organization_id,receipt,status,revision,consent_at,updated_at FROM job_fair_registrations WHERE user_id=? AND event_id<? ORDER BY event_id DESC LIMIT ?",uid,before,limit+1);return HubService.pageResult(list,limit);}
 public Map<String,Object> counts(CountQuery query){if(query==null||query.organizationId()<1||query.eventIds()==null||query.eventIds().isEmpty()||query.eventIds().size()>50||query.eventIds().stream().anyMatch(id->id==null||id<1)||new HashSet<>(query.eventIds()).size()!=query.eventIds().size())bad("Consulta agregada inválida.");var counts=new TreeMap<String,Long>();query.eventIds().forEach(id->counts.put(id.toString(),0L));var args=new ArrayList<Object>();args.add(query.organizationId());args.addAll(query.eventIds());for(var row:db.queryForList("SELECT event_id,count(*) AS total FROM job_fair_registrations WHERE organization_id=? AND status='REGISTERED' AND event_id IN ("+String.join(",",Collections.nCopies(query.eventIds().size(),"?"))+") GROUP BY event_id",args.toArray()))counts.put(row.get("event_id").toString(),number(row,"total"));return Map.of("counts",counts,"observedAt",Instant.now().toString(),"notice","Contas inscritas nesta trilha, sem dados identificáveis e sem deduplicação entre plataformas.");}
}
